            aOrbiterF = RotL64((aOrbiterF * 0x03A69AAE45B4E213ULL), 5U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x4F858790515BCD6BULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xA4108BB0ADBB3FBDULL;
