            aOrbiterJ = (((aWandererA + RotL64(aScatter, 21U)) + RotL64(aCarry, 5U)) + 0x6D59AC272E8FEA96ULL) + aTwistOrbiterAssignSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterC = (aWandererG + RotL64(aCross, 3U)) + 0x0ED73032DD0E14A3ULL;
            aOrbiterD = (((aWandererC + RotL64(aPrevious, 27U)) + RotL64(aCarry, 43U)) + 0x4356B71BC14B2746ULL) + aTwistOrbiterAssignSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterG = (aWandererJ + RotL64(aIngress, 48U)) + 0x3BFB35CFC9A7A68BULL;
            aOrbiterH = (aWandererB + RotL64(aPrevious, 11U)) + 0x1095E84664A99B6BULL;
            aOrbiterB = (aWandererF + RotL64(aIngress, 35U)) + 0x9391FCB3BE473D48ULL;
            aOrbiterI = ((aWandererE + RotL64(aCross, 57U)) + RotL64(aCarry, 27U)) + 0x64F26D6A4862CE89ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x8EDC18F384D66127ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x5CF04BD11F8DD66FULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB75DFA6A7B368C85ULL), 57U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x522D1DD71557331AULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x70722478AEAAD0BFULL;
