            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x187D73584AC8DEA7ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x21C48CC55C3DA23BULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 10U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x1598A325E5A0870DULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x5CD7A8E392B34A68ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xD6E4C109BEC0715BULL;
            aOrbiterG = RotL64((aOrbiterG * 0xE1B2D3F71304E41DULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xB76A2E9B2CC60C64ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xAF2940F4227B0C3BULL;
            aOrbiterI = RotL64((aOrbiterI * 0x0627F0F7DDD9D6C9ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xF2AE2F70A5C5B6A1ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xD1EA60411DA705DCULL;
            aOrbiterC = RotL64((aOrbiterC * 0x486BEAB2D2AE2D25ULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xB2AC0638FB8997BEULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x085A5F92E8385E9BULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xC8E2407A461131D7ULL), 29U);
