            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFireLaneD[((aIndex + 12783U)) & S_BLOCK1], 35U) ^ RotL64(aEarthLaneA[((aIndex + 16316U)) & S_BLOCK1], 51U));
            aIngress ^= RotL64(pSnowLaneB[((aIndex + 11482U)) & S_BLOCK1], 24U);
