            aScatter = (RotL64(aCarry, 27U) + RotL64(aPrevious, 56U)) + (RotL64(aCross, 39U) ^ RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
