            //
            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0x732F5527DA560A50ULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x6E2A3312A32A119FULL;
