            aOrbiterH = RotL64((aOrbiterH * 0x5A1E61B714CD7959ULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xC5C313DD29B9C4AEULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x28BCB3CA3952104DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x215E55B0A262C1CBULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0x4B0180E7585C3F24ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0xD68B7D6FA6AAE4A2ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x65DCFB30B839167FULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xA37E9E918DF73EECULL;
