            aOrbiterK = RotL64((aOrbiterK * 0x106C78E0DA56C81DULL), 41U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterJ, 53U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterK, 57U));
            aIngress = aIngress + (RotL64(aOrbiterH, 43U) ^ aOrbiterI);
            aIngress = aIngress + (RotL64(aOrbiterE, 30U) ^ aOrbiterD);
            aIngress = aIngress + RotL64(aOrbiterF, 5U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererD = aWandererD + (((RotL64(aIngress, 52U) + aOrbiterA) + RotL64(aOrbiterK, 56U)) + RotL64(aCarry, 21U));
            aWandererA = aWandererA ^ (((RotL64(aScatter, 39U) + aOrbiterE) + RotL64(aOrbiterA, 5U)) + aKeyRotateWandererUpdateSaltF[((aIndex + 22U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 57U) + aOrbiterJ) + RotL64(aOrbiterE, 47U)) + RotL64(aCarry, 39U));
            aWandererG = aWandererG ^ ((RotL64(aCross, 35U) + RotL64(aOrbiterJ, 43U)) + aOrbiterH);
            aWandererK = aWandererK + (((RotL64(aIngress, 47U) + aOrbiterI) + RotL64(aOrbiterE, 29U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterB, 11U)) + aOrbiterF);
