            aOrbiterG = (aWandererF + RotL64(aIngress, 13U)) + 0x498E19312F3C4C25ULL;
            aOrbiterA = (((aWandererG + RotL64(aPrevious, 39U)) + RotL64(aCarry, 27U)) + 0xA7EE978A29873F1DULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterE = (((aWandererH + RotL64(aCross, 35U)) + RotL64(aCarry, 5U)) + 0x614DFA1F9B333BE1ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aScatter, 29U)) + RotL64(aCarry, 57U)) + 0xD7C7E31A982912BEULL;
            aOrbiterF = (aWandererC + RotL64(aCross, 56U)) + 0x6B0F244E94B16CA1ULL;
