            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x27145132362EF738ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x58D6F0777F76C217ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x2EBF47ADB551DD81ULL), 23U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x1E2A07E2F204E59DULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 14U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xEF4FEBA3ABC95B86ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4C1185A6D3D84155ULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x2FA20FDA0831EDF3ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x8DA50CAB89438373ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x89C7B701166CED2BULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xADB9FB8C8ABFAFE9ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xEDE0864677739743ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE0B2DB9BA26302EFULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xBE1404908A5D1EF2ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x6CAB61303981B29DULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xD89948E2C0E0FDE5ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xCE6C5E6C9176D961ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x4617BC3A35B6B81EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x109E95DC194F9B2DULL), 19U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xA5ABA326D7B2D4D2ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x975E5CD036FD0E9AULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE18BDD375D2BB1D9ULL), 3U);
