            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xD18F702125808658ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x5DAB7E6824603AECULL;
            aOrbiterF = RotL64((aOrbiterF * 0xA72F9E378AEC50A7ULL), 35U);
            //
            aIngress = RotL64(aOrbiterH, 26U) ^ aOrbiterE;
            aIngress = aIngress + (RotL64(aOrbiterG, 35U) ^ aOrbiterK);
