            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 7696U)) & W_KEY1], 39U) ^ RotL64(aLightningLaneD[((aIndex + 7718U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 6U) + RotL64(aCarry, 47U)) ^ (RotL64(aCross, 19U) + RotL64(aIngress, 35U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterD = ((aWandererD + RotL64(aCross, 41U)) + 0xD278F6AC9EDE2BC3ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aScatter, 21U)) + 0xF309C3B2E4ACC0B1ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterB = (aWandererJ + RotL64(aPrevious, 35U)) + 0x9BECD53C30A18BEFULL;
            aOrbiterJ = (aWandererC + RotL64(aIngress, 13U)) + 0x2C6826DBC1462A06ULL;
            aOrbiterE = ((aWandererE + RotL64(aCross, 28U)) + RotL64(aCarry, 13U)) + 0x609F20C56F32C66CULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 57U)) + 0xF7C23F948CA4B35DULL;
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 3U)) + RotL64(aCarry, 3U)) + 0xA8B51D859EC9B639ULL;
            aOrbiterC = ((aWandererI + RotL64(aScatter, 47U)) + RotL64(aCarry, 29U)) + 0x85DC1DE79EE96813ULL;
            aOrbiterH = (aWandererA + RotL64(aCross, 24U)) + 0x243773C1864F30EBULL;
            aOrbiterK = (aWandererK + RotL64(aIngress, 53U)) + 0xBC981D790B98CDB4ULL;
            aOrbiterI = (aWandererG + RotL64(aPrevious, 37U)) + 0x7D398E6C8545E7C5ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xE149976F836E1B13ULL;
