            aCross ^= (RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 6674U)) & S_BLOCK1], 19U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 3746U)) & W_KEY1], 58U));
