            //
            aOrbiterJ = (aWandererE + RotL64(aScatter, 60U)) + 0xCFAF53B8DDD79633ULL;
            aOrbiterC = (((aWandererB + RotL64(aCross, 27U)) + RotL64(aCarry, 11U)) + 0x36F7AE3D8CC06734ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
