            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xD953CDE5EF87C70EULL) + aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x4175E470E85BD405ULL;
