            aOrbiterC = ((aWandererA + RotL64(aPrevious, 51U)) + RotL64(aCarry, 51U)) + 0x34F2E6C6EF080F3BULL;
            aOrbiterB = (aWandererB + RotL64(aCross, 27U)) + 0x5C5A9EB5A276D134ULL;
