            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x5BAA4C5DE13DFBA6ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x9890AF9A26ECB774ULL) ^ aKeySpawnOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
