            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x4C2E69DBCDA04B99ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x432434CE4818DDB9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB792354901231BDBULL), 23U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x7B71BAF91D487B52ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x3821AA1F298D83ACULL;
            aOrbiterC = RotL64((aOrbiterC * 0xB2C8A05E6FA7BBCFULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x8FD408326809AF83ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x1B5017F7D24A557FULL) ^ aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x5394BD5CD6CE8499ULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x11E03D15BB31EBE7ULL;
